/**
 * CONTEXT MULTIPLEXER (v4.8 - Streamlined Reflection State Sync)
 * Responsibility: Merging upstream order suitcases with subflow SOP outputs and loop feedback.
 * Goal: Eliminate the Round 1 reset loop bottleneck by utilizing native n8n input states.
 * Execution Mode: Run once for each item.
 */

// 1. INGRESS DISCOVERY
// If the workflow has looped back, $json IS the retry packet coming from your aggregator!
const incoming = $json;

// Check the wire: Is this active execution a retry cycle from the loop?
const isRetry = incoming.audit_verdict === "RETRY";

// 2. PRIORITY MERGE LOGIC (If an Auditor demanded a RETRY)
if (isRetry) {
    return {
        // --- CORE OPERATIONAL DATA (Maintained from the loop feedback wire) ---
        order_id: incoming.order_id,
        problem_archetype: incoming.problem_archetype,
        archetype_description: incoming.archetype_description,
        mapped_domain: incoming.mapped_domain || "General",
        order_details: incoming.order_details, 
        drivers: incoming.drivers || [],
        sop_context: incoming.sop_context,

        // --- DYNAMIC STATE DATA (Successfully preserves the incremented round!) ---
        audit_round: Number(incoming.audit_round || 2), 
        is_reflection: true,
        feedback_instruction: incoming.feedback_instruction || "Plan rejected. Please revise based on SOP constraints.",

        // ─── STATE telemetry: Forward rolling loop-back critique logs smoothly down the wire ───
        rejection_reasons_log: incoming.rejection_reasons_log || ""
    };
}

// 3. DEFAULT CASE: ROUND 1 (Fresh Ingress from Output_Data_Normalizer / Subflow)
// If it's the very first run, we defensively ensure our data suitcase is fully loaded.
let suitcase = incoming;
if (!suitcase.order_details) {
    try {
        suitcase = $('Output_Data_Normalizer').first().json;
    } catch(e) {
        // Fallback to incoming if normalizer is out of scope
    }
}

return {
    // --- CORE OPERATIONAL DATA ---
    order_id: suitcase.order_id,
    problem_archetype: suitcase.problem_archetype,
    archetype_description: suitcase.archetype_description,
    mapped_domain: suitcase.mapped_domain || "General",
    order_details: suitcase.order_details,
    drivers: suitcase.drivers || [],
    sop_context: incoming.sop_context || suitcase.sop_context || "No SOP context available.",

    // --- INITIAL STATE DATA ---
    audit_round: Number(suitcase.audit_round) || 1,
    is_reflection: suitcase.is_reflection || false,
    feedback_instruction: "None. This is the initial planning attempt.",

    // ─── STATE TELEMETRY: Seamlessly pass initial critique values into the active loop ───
    rejection_reasons_log: suitcase.rejection_reasons_log || ""
};

// Get the incoming payload, automatically handling both wrapped or flat JSON inputs
const inputData = $input.first().json;
const payload = inputData.body ? inputData.body : inputData;

if (!payload || !payload.order_id) {
    throw new Error("Data Normalizer Error: Incoming Webhook payload is missing order data.");
}

// Clean up the annoying leading ":  " artifact from the python description string
let cleanDescription = payload.archetype_description || "No description provided.";
if (cleanDescription.startsWith(":")) {
    cleanDescription = cleanDescription.replace(/^:\s*/, "");
}

// Output a perfectly structured, clean, flat JSON object for downstream nodes
return {
    order_id: payload.order_id,
    problem_archetype: payload.problem_archetype,
    archetype_description: cleanDescription,
    order_details: payload.order_details,
    drivers: payload.drivers || [],

    // ─── STATE ARRAYS: Initialize master state parameters as the root loop anchors ───
    audit_round: 1,
    is_reflection: false,
    rejection_reasons_log: "",

    // ─── NEW: Fixed Start Timestamp ───
    start_time: new Date().toISOString()
};

// 1. Unpack the text classification result from the immediate input node
const llmResult = $json;

// 2. Pull the original data suitcase from the first normalizer node
const sourceData = $('Input_Data_Normalizer').first().json;

// 3. Extract the domain name defensively from the router text
let domain = "General"; 
if (llmResult.mapped_domain) {
    domain = llmResult.mapped_domain;
} else if (llmResult.text) {
    domain = llmResult.text;
} else if (typeof llmResult === 'string') {
    domain = llmResult;
}
domain = domain.trim();

// 4. Repackage all components into a comprehensive data envelope
return {
    order_id: sourceData.order_id,
    problem_archetype: sourceData.problem_archetype,
    archetype_description: sourceData.archetype_description,
    mapped_domain: domain, 
    order_details: sourceData.order_details, 

    // ALIGNED: Kept as 'drivers' to match what 'SOP_Normalize_Input' expects
    drivers: sourceData.drivers || [], 

    // Carry forward master loop control metrics cleanly without tokens
    audit_round: sourceData.audit_round || 1,
    is_reflection: sourceData.is_reflection || false,
    rejection_reasons_log: sourceData.rejection_reasons_log || ""
};

/**
 * FORMAT RAGAS PAYLOAD (v2.1 - Clean Telemetry Mapping)
 * Responsibility: Compile the raw text triplet using the top SHAP anomaly impact features.
 * Maps pre-calculated time metrics directly from Success_Total_Time without fallback fakes.
 */

// 1. TIMING METRICS (Pure mapping from upstream Success_Total_Time node - NO fakes)
const finalEvaluatorOutput = $json; 
const executionTimeSec = finalEvaluatorOutput.total_execution_time_sec || 0;

// 2. STATE & METADATA EXTRACTION
const normalizedInput = $('Input_Data_Normalizer').first().json;

// 3. DYNAMIC QUESTION ASSEMBLY (FIXED: Case-insensitive driver array matching)
const problemArchetype = finalEvaluatorOutput.problem_archetype || normalizedInput.problem_archetype || "Unknown Anomaly";

let criticalFeatures = [];
try {
    const rawDrivers = finalEvaluatorOutput.drivers || finalEvaluatorOutput.Planning || 
                       normalizedInput.drivers || normalizedInput.Planning;

    if (Array.isArray(rawDrivers)) {
        criticalFeatures = rawDrivers.slice(0, 2).map(f => f.feature);
    }
} catch (e) {
    criticalFeatures = [];
}

if (criticalFeatures.length === 0) {
    criticalFeatures = Object.keys(normalizedInput).slice(0, 2);
}

const dynamicQuestion = `Policy violation triggered for archetype [${problemArchetype}]. Critical systemic variances identified in features: ${criticalFeatures.join(', ')}. How should the operations group mitigate this risk according to corporate governance constraints?`;

// 4. CONTEXT EXTRACTION (Preserved RAGAS Triplet Architecture)
let retrievedContext = "No context chunks logged";
try {
    const retrievalNode = $("Call 'SOP_RAG_Retrieval_Workflow'").first().json;
    retrievedContext = retrievalNode.sop_context || "No context chunks logged";
} catch (e) {
    retrievedContext = "Context retrieval mapping error";
}

// 5. ANSWER EXTRACTION (Preserved RAGAS Triplet Architecture)
let generatedAnswer = "";
const planObj = finalEvaluatorOutput.final_plan || {};
if (planObj.rationale) {
    generatedAnswer += `Rationale: ${planObj.rationale}\n\n`;
}
if (Array.isArray(planObj.steps)) {
    generatedAnswer += "Execution Steps:\n" + planObj.steps.map(s => `Step ${s.step}: ${s.action} (Ref: ${s.sop_ref || 'SOP Rules'})`).join("\n");
}
if (finalEvaluatorOutput.communication) {
    generatedAnswer += `\n\nCommunication Response: ${finalEvaluatorOutput.communication}`;
} else if (planObj.communication) {
    generatedAnswer += `\n\nCommunication Response: ${planObj.communication}`;
}

if (!generatedAnswer.trim()) {
    generatedAnswer = typeof finalEvaluatorOutput === 'string' ? finalEvaluatorOutput : "No plan compiled";
}

// 6. HISTORICAL AUDIT LOG EXTRACTION
const rejectionReasonsLog = finalEvaluatorOutput.rejection_reasons_log || "None (Passed on First Attempt)";

// 7. RETURN UNIFIED TRANSIT DATA ENVELOPE
return [
  {
    json: {
      ...finalEvaluatorOutput, // Carries forward start_time, end_time, total_execution_time_ms/sec cleanly
      execution_time_sec: executionTimeSec, // Clean pass-through of the true numeric seconds
      rejection_reasons_log: rejectionReasonsLog,
      rag_triplet: {
        archetype: problemArchetype,
        question: dynamicQuestion,
        context: retrievedContext,
        answer: generatedAnswer
      }
    }
  }
];

/**
 * SUCCESS TOTAL TIME (v1.1 - Production Ledger Pass-Through)
 * Responsibility: Capture precise end metrics while dynamically preserving 
 * 100% of the upstream data payload for direct Google Sheets appending.
 * Execution Mode: Run once for each item.
 */

// 1. Capture the complete incoming data suitcase
const incomingSuitcase = $json;

let startIsoString = "";
let endIsoString = new Date().toISOString();
let totalExecutionTimeMs = 0;
let totalExecutionTimeSec = 0;

try {
    // Look back to the front gate normalizer to grab the fixed start timestamp
    startIsoString = $('Input_Data_Normalizer').first().json.start_time;

    if (startIsoString) {
        const startTime = new Date(startIsoString).getTime();
        const endTime = new Date(endIsoString).getTime();

        // Calculate the execution time metrics
        totalExecutionTimeMs = endTime - startTime;
        totalExecutionTimeSec = parseFloat((totalExecutionTimeMs / 1000).toFixed(2));
    }
} catch (err) {
    // Fallback protection for debugging isolated nodes
    startIsoString = incomingSuitcase.start_time || new Date().toISOString();
    totalExecutionTimeMs = 0;
    totalExecutionTimeSec = 0.00;
}

// 2. Return the absolute entire payload + the newly computed timeline metrics
return {
    ...incomingSuitcase, // <-- Automatically preserves ALL original fields for Google Sheets / RAGAS

    // Appends clean timeline telemetry onto the suitcase
    start_time: startIsoString,
    end_time: endIsoString,
    total_execution_time_ms: totalExecutionTimeMs,
    total_execution_time_sec: totalExecutionTimeSec
};

/**
 * FAILURE TOTAL TIME (v1.1 - Production Failure Ledger Pass-Through)
 * Responsibility: Capture precise end metrics for the max-escalation path,
 * dynamically preserving 100% of the looped data payload for the failure sheet.
 * Execution Mode: Run once for each item.
 */

// 1. Capture the complete incoming failed iteration suitcase
const incomingSuitcase = $json;

let startIsoString = "";
let endIsoString = new Date().toISOString();
let totalExecutionTimeMs = 0;
let totalExecutionTimeSec = 0;

try {
    // Look back to the front gate normalizer to grab the fixed start timestamp
    startIsoString = $('Input_Data_Normalizer').first().json.start_time;

    if (startIsoString) {
        const startTime = new Date(startIsoString).getTime();
        const endTime = new Date(endIsoString).getTime();

        // Calculate the execution time metrics
        totalExecutionTimeMs = endTime - startTime;
        totalExecutionTimeSec = parseFloat((totalExecutionTimeMs / 1000).toFixed(2));
    }
} catch (err) {
    // Fallback protection for debugging isolated nodes
    startIsoString = incomingSuitcase.start_time || new Date().toISOString();
    totalExecutionTimeMs = 0;
    totalExecutionTimeSec = 0.00;
}

// 2. Return the absolute entire payload + the newly computed timeline metrics
return {
    ...incomingSuitcase, // <-- Automatically preserves ALL loop tracking fields for your Google Sheet

    // Appends clean failure timeline telemetry onto the suitcase
    start_time: startIsoString,
    end_time: endIsoString,
    total_execution_time_ms: totalExecutionTimeMs,
    total_execution_time_sec: totalExecutionTimeSec
};
